// 简单的字体加载监测与回退逻辑：若在限定时间内未检测到 LXGW WenKai 可用，则注入 jsDelivr 的 WebFont 样式
      // 说明：
      // 1) 使用 Font Loading API 的 document.fonts.check 检测字体是否可用；
      // 2) 若不可用，则追加一个 link 指向 jsDelivr 的 WebFont CSS 包；
      // 3) 该包会声明 @font-face 并提供多种格式，提升加载成功率。
      (function(){
        function ensureLXGW(){
          var isSupported = false;
          try {
            // 检测字体是否可用（若系统或 GoogleFonts 已加载，会返回 true）
            isSupported = document.fonts && document.fonts.check && document.fonts.check('16px "LXGW WenKai"');
          } catch(e) {
            isSupported = false;
          }

          if (!isSupported) {
            // 注入 jsDelivr 的 WebFont 样式（npm 包方式），作为回退
            var fallback = document.createElement('link');
            fallback.rel = 'stylesheet';
            fallback.href = 'https://cdn.jsdelivr.net/npm/lxgw-wenkai-webfont@latest/style.css';
            document.head.appendChild(fallback);
          }
        }

        function ensureSmiley(){
          var ok = false;
          try {
            ok = document.fonts && document.fonts.check && document.fonts.check('16px "Smiley Sans"');
          } catch(e) {
            ok = false;
          }
          if (!ok) {
            var link = document.createElement('link');
            link.rel = 'stylesheet';
            link.href = 'https://cdn.jsdelivr.net/npm/font-smiley-sans@1.0.0/style.min.css';
            document.head.appendChild(link);
          }
        }

        // 等待一段时间让 Google Fonts 先尝试加载，再进行检测
        window.addEventListener('load', function(){
          setTimeout(function(){ ensureLXGW(); ensureSmiley(); }, 1800);
        });
      })();

// 如果CDN加载失败，使用备选方案，并且为CSS引入追加时间戳以避免缓存
      window.addEventListener('DOMContentLoaded', function() {
        // 为 Font Awesome 样式追加时间戳参数，避免缓存
        try {
          var linkEl = document.getElementById('fa-css');
          if (linkEl && linkEl.href) {
            var url = new URL(linkEl.href);
            url.searchParams.set('ts', Date.now().toString());
            linkEl.href = url.toString();
          }
        } catch (e) {
          console.warn('追加时间戳到字体样式失败：', e);
        }

        if (typeof window.FontAwesome === 'undefined') {
          console.warn('Font Awesome CDN加载失败，尝试使用本地版本');
          // TODO: 可添加本地回退方案，例如 /public/font-awesome.min.css
        }
      });

